"package main

import (
	"context"
	"fmt"
	"imc-server/internal/database"
	"imc-server/internal/repository"
	"imc-server/internal/utils"
)

func main() {
	database.ConnectDatabase()
	defer database.CloseDatabase()

	repo := repository.NewStoreRepository()
	stores, err := repo.GetAll(context.Background())
	if err != nil {
		fmt.Printf("Failed to fetch stores: %v\n", err)
		return
	}

	for _, s := range stores {
		if s.IsActive && s.RadioType == "server" && s.HarborPort != nil && *s.HarborPort >= 7001 {
			fmt.Printf("Starting radio container for store %s (Harbor: %d)...\n", s.StoreName, *s.HarborPort)
			if err := utils.StartStoreDockerContainer(s); err != nil {
				fmt.Printf("Error starting store %s: %v\n", s.StoreName, err)
			}
		}
	}

	if err := utils.RebuildAndReloadCaddy(); err != nil {
		fmt.Printf("Error rebuilding Caddy: %v\n", err)
	} else {
		fmt.Println("Successfully rebuilt and reloaded Caddy configuration!")
	}
}
"

